insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_rough','rough','adjective','not exact or finished; done quickly to give a general idea','[{"senseId":"rough_1","meaning":"not exact or finished; done quickly to give a general idea","acceptedParaphrases":["approximate","not detailed or final"],"masteryContexts":[{"contextId":"u8_31_rough_meaning","text":"I can only give you a rough estimate of the cost until I see the damage.","meaning":"approximate and not exact","wrongMeanings":["exact and fully checked","very high and unfair","written and signed"]},{"contextId":"u8_31_rough_paraphrase","text":"Before the meeting, Sami wrote a rough plan on the back of an envelope.","meaning":"quick and not finished","wrongMeanings":["neat and carefully typed","secret and hidden","long and very detailed"]}],"situationDistractors":["An accountant checked every number in the report twice.","A designer printed the final version of a poster.","An engineer measured a pipe to the nearest millimetre.","A manager signed the finished contract.","A printer produced a perfect copy of the brochure.","A scientist recorded the exact temperature every hour."],"gapDistractors":[{"contextId":"u8_31_rough_gap_1","answer":"rough","wrong":["sustainable","relentless","responsible"]},{"contextId":"u8_31_rough_gap_2","answer":"rough","wrong":["sustainable","traditional","responsible"]},{"contextId":"u8_31_rough_gap_3","answer":"rough","wrong":["sustainable","relentless","significant"]}],"spellingErrors":["ruff","rouhg","rogh","rouf","roughe","rugh"],"masteryPassages":[{"passageId":"u8_31_rough_passage_1","contextId":"u8_31_rough_gap_1","text":"The builder looked quickly at the kitchen and said the work would cost about two thousand pounds. He explained that it was only a ____ estimate and that the final price might be different.","answer":"rough"},{"passageId":"u8_31_rough_passage_2","contextId":"u8_31_rough_gap_2","text":"Before she wrote the report, Lina scribbled a ____ plan on a piece of paper. It had arrows and a few key words, but no full sentences.","answer":"rough"}],"contextDependentParaphrases":[],"wrongParaphrases":["exact","official","permanent"],"misleadingDistractors":["exact and carefully checked","finished and ready to sell","smooth and pleasant to touch"],"teacherNote":"Adjective: not exact or finished; giving a general idea (a rough sketch, a rough estimate, a rough idea). Boundary: rough also means not smooth (rough skin) or difficult and unpleasant (a rough day); Unit 8 teaches the \"not exact\" sense used at work. The adverb roughly (approximately) is useful, but no three-form family fits this sense."}]'::jsonb,'[]'::jsonb,'["a rough idea","a rough estimate","a rough sketch"]'::jsonb,'live'),
('vocab_significant_8','significant','adjective','large or important enough to have a noticeable effect','[{"senseId":"significant_8_1","meaning":"large or important enough to have a noticeable effect","acceptedParaphrases":["important","large enough to notice"],"masteryContexts":[{"contextId":"u8_32_significant_8_meaning","text":"There has been a significant rise in the number of people working from home.","meaning":"large enough to be noticed","wrongMeanings":["too small to measure","sudden but short","expected by everyone"]},{"contextId":"u8_32_significant_8_paraphrase","text":"Her research played a significant part in the development of the vaccine.","meaning":"important and having an effect","wrongMeanings":["tiny and not useful","secret and hidden","funny and surprising"]}],"situationDistractors":["Sales rose by one pound in a whole year.","A worker moved her desk two centimetres to the left.","A shop changed the colour of its receipt paper slightly.","The temperature in the office went up by a tenth of a degree.","A manager added a comma to a long report.","The price of a car went up by one penny."],"gapDistractors":[{"contextId":"u8_32_significant_8_gap_1","answer":"significant","wrong":["curved","qualified","responsible"]},{"contextId":"u8_32_significant_8_gap_2","answer":"significant","wrong":["curved","responsible","rough"]},{"contextId":"u8_32_significant_8_gap_3","answer":"significant","wrong":["curved","responsible","qualified"]}],"spellingErrors":["signifacant","significent","signficant","signifficant","significat","sinificant"],"wordFamilyForms":[{"form":"significant","partOfSpeech":"adjective","example":"The report found a significant fall in accidents at work.","pedagogicallyUseful":true},{"form":"significance","partOfSpeech":"noun","example":"The manager explained the significance of the new contract.","pedagogicallyUseful":true,"altExample":"Few people understood the significance of the discovery at the time."},{"form":"significantly","partOfSpeech":"adverb","example":"Sales have improved significantly since the new website went live.","pedagogicallyUseful":true,"altExample":"The new machines are significantly faster than the old ones."}],"masteryPassages":[{"passageId":"u8_32_significant_8_passage_1","contextId":"u8_32_significant_8_gap_1","text":"Before the new road was built, the café served about fifty customers a day. Now it serves over two hundred. The road has made a ____ difference to the business.","answer":"significant"},{"passageId":"u8_32_significant_8_passage_2","contextId":"u8_32_significant_8_gap_2","text":"Last year, the factory used forty per cent less water than the year before. This is a ____ achievement, and other factories want to copy its methods.","answer":"significant"}],"contextDependentParaphrases":[],"wrongParaphrases":["unknown","temporary","accidental"],"misleadingDistractors":["too small to make any difference","completely unknown to most people","happening only by chance"],"teacherNote":"Adjective: large or important enough to have a noticeable effect (a significant increase, a significant role). Unit 8 uses it for changes and results at work; Unit 1 taught the same core sense. The noun significance and the adverb significantly are taught in the Word Family pathway."}]'::jsonb,'["significance","significantly"]'::jsonb,'["a significant increase","a significant role","significant changes"]'::jsonb,'live'),
('vocab_source','source','noun','the place, person or thing that something comes from','[{"senseId":"source_1","meaning":"the place, person or thing that something comes from","acceptedParaphrases":["origin","where something comes from"],"masteryContexts":[{"contextId":"u8_33_source_meaning","text":"Solar panels provide a clean source of energy for the factory.","meaning":"a place or thing that something comes from","wrongMeanings":["a place where something is stored","a machine that wastes something","a rule that limits something"]},{"contextId":"u8_33_source_paraphrase","text":"The journalist would not name the source of her information.","meaning":"the person who gave something","wrongMeanings":["the person who paid for something","the person who printed something","the person who doubted something"]}],"situationDistractors":["A worker threw an empty bottle into the recycling bin.","A shop sold the last loaf of bread of the day.","A manager locked the door at the end of the day.","A cleaner wiped the tables after lunch.","A driver parked the van outside the warehouse.","A customer returned a broken toaster."],"gapDistractors":[{"contextId":"u8_33_source_gap_1","answer":"source","wrong":["response","feature","minority"]},{"contextId":"u8_33_source_gap_2","answer":"source","wrong":["response","assignment","minority"]},{"contextId":"u8_33_source_gap_3","answer":"source","wrong":["response","landscape","feature"]}],"spellingErrors":["sorce","sourse","soruce","sourc","souce","sourece"],"masteryPassages":[{"passageId":"u8_33_source_passage_1","contextId":"u8_33_source_gap_1","text":"Most families in the valley grow coffee. Selling the beans is their main ____ of income, so a bad harvest is a disaster.","answer":"source"},{"passageId":"u8_33_source_passage_2","contextId":"u8_33_source_gap_2","text":"The river begins as a small stream high in the mountains. Engineers walked for two days to find its ____.","answer":"source"}],"contextDependentParaphrases":[],"wrongParaphrases":["destination","owner","price"],"misleadingDistractors":["the place where something ends","the person who buys something","the price of something"],"teacherNote":"Noun: the place, person or thing that something comes from (a source of income, a source of energy, a source of information). Boundary: a source is where something starts or comes from; a resource is something useful that you have. No family is taught."}]'::jsonb,'[]'::jsonb,'["a source of income","a source of energy","a reliable source"]'::jsonb,'live'),
('vocab_specialise_8','specialise','verb','to concentrate your work or study on one particular area and become an expert in it','[{"senseId":"specialise_8_1","meaning":"to concentrate your work or study on one particular area and become an expert in it","acceptedParaphrases":["focus on one area","become an expert in one subject"],"masteryContexts":[{"contextId":"u8_34_specialise_8_meaning","text":"Dr Chen decided to specialise in heart surgery after working in the emergency department.","meaning":"to focus on one area of work","wrongMeanings":["to leave a job completely","to work in every area","to teach other people"]},{"contextId":"u8_34_specialise_8_paraphrase","text":"The company used to sell all kinds of furniture, but now it wants to specialise in office chairs.","meaning":"to concentrate on one type of product","wrongMeanings":["to stop making a product","to copy another company","to lower all its prices"]}],"situationDistractors":["A shop sells food, clothes, toys and garden tools.","A worker does a different job in the company every week.","A student studies ten subjects at school.","A handyman fixes cars, roofs, computers and bikes.","A farmer grows twenty different crops.","A writer produces poems, novels, adverts and recipes."],"gapDistractors":[{"contextId":"u8_34_specialise_8_gap_1","answer":"specialise","wrong":["resign","retire","complain"]},{"contextId":"u8_34_specialise_8_gap_2","answer":"specialise","wrong":["retire","resign","apologise"]},{"contextId":"u8_34_specialise_8_gap_3","answer":"specialise","wrong":["retire","resign","argue"]}],"spellingErrors":["specialize","specalise","speciallise","spesialise","specialice","specailise"],"wordFamilyForms":[{"form":"specialise","partOfSpeech":"verb","example":"She hopes to specialise in children’s medicine.","pedagogicallyUseful":true},{"form":"specialist","partOfSpeech":"noun","example":"The doctor sent him to a specialist at the city hospital.","pedagogicallyUseful":true,"altExample":"The company hired a specialist to repair the old clock tower."},{"form":"specialised","partOfSpeech":"adjective","example":"The job requires specialised training in electronics.","pedagogicallyUseful":true,"altExample":"Only a few shops sell such specialised equipment."}],"masteryPassages":[{"passageId":"u8_34_specialise_8_passage_1","contextId":"u8_34_specialise_8_gap_1","text":"Lina enjoyed every part of her law degree, but employment cases interested her most. After graduating, she decided to ____ in that area, and now she advises workers about their rights.","answer":"specialise"},{"passageId":"u8_34_specialise_8_passage_2","contextId":"u8_34_specialise_8_gap_2","text":"The small bakery used to make everything from pizzas to wedding cakes. Now it has chosen to ____ in bread, and its sourdough is famous across the city.","answer":"specialise"}],"contextDependentParaphrases":[],"wrongParaphrases":["work in many areas","retire from one job","move to another firm"],"misleadingDistractors":["to work in many different areas at once","to give up a job in order to study","to move to a new company"],"teacherNote":"Verb: to focus your work or study on one area and become an expert in it (specialise in something). British spelling specialise is the accepted answer. Unit 5 taught the same core sense; Unit 8 uses it for careers. The noun specialist and the adjective specialised are taught in the Word Family pathway."}]'::jsonb,'["specialist","specialised"]'::jsonb,'["specialise in","choose to specialise","specialise in a particular area"]'::jsonb,'live'),
('vocab_structures','structures','noun','things that have been built, such as buildings, bridges and towers','[{"senseId":"structures_1","meaning":"things that have been built, such as buildings, bridges and towers","acceptedParaphrases":["things that are built","constructions"],"masteryContexts":[{"contextId":"u8_35_structures_meaning","text":"The Eiffel Tower is one of the most famous structures in the world.","meaning":"things that have been built","wrongMeanings":["natural places such as hills","famous people in history","old books and maps"]},{"contextId":"u8_35_structures_paraphrase","text":"After the earthquake, engineers checked all the structures in the city for cracks.","meaning":"buildings and bridges","wrongMeanings":["roads and cars","rivers and lakes","parks and trees"]}],"situationDistractors":["A farmer ploughed a field ready for planting.","A hiker walked through a forest with no buildings.","A diver swam among the rocks in the sea.","A gardener cut the grass in a park.","Children played on a sandy beach.","A shepherd watched his sheep on a hill."],"gapDistractors":[{"contextId":"u8_35_structures_gap_1","answer":"structures","wrong":["ingredients","regulations","elements"]},{"contextId":"u8_35_structures_gap_2","answer":"structures","wrong":["ingredients","regulations","inspectors"]},{"contextId":"u8_35_structures_gap_3","answer":"structures","wrong":["ingredients","regulations","elements"]}],"spellingErrors":["structurs","stuctures","structeres","strucktures","structuers","strutcures"],"masteryPassages":[{"passageId":"u8_35_structures_passage_1","contextId":"u8_35_structures_gap_1","text":"The city is famous for its bridges and towers. Some of these ____ are over five hundred years old, and engineers check them every year.","answer":"structures"},{"passageId":"u8_35_structures_passage_2","contextId":"u8_35_structures_gap_2","text":"Before the festival, workers put up tents, stages and lighting towers in the park. All these temporary ____ were taken down after three days.","answer":"structures"}],"contextDependentParaphrases":[],"wrongParaphrases":["things that grow wild","things that are eaten","things that are written"],"misleadingDistractors":["natural features such as hills and rivers","plans drawn before building starts","people who design buildings"],"teacherNote":"Plural noun: things that have been built, such as buildings, bridges, towers and walls (tall structures, steel structures). Boundary: structure can also mean the way parts are organised (the structure of an essay); Unit 8 teaches the built-object sense. No family is taught."}]'::jsonb,'[]'::jsonb,'["tall structures","steel structures","temporary structures"]'::jsonb,'live'),
('vocab_sustainable','sustainable','adjective','able to continue for a long time without harming the environment or using up natural resources','[{"senseId":"sustainable_1","meaning":"able to continue for a long time without harming the environment or using up natural resources","acceptedParaphrases":["environmentally friendly","able to last without harming nature"],"masteryContexts":[{"contextId":"u8_36_sustainable_meaning","text":"Solar and wind power are sustainable sources of energy.","meaning":"able to continue without harming the planet","wrongMeanings":["very expensive to use","dangerous to people","impossible to store"]},{"contextId":"u8_36_sustainable_paraphrase","text":"The café only buys sustainable fish that are caught without damaging the sea.","meaning":"obtained without harming the environment","wrongMeanings":["caught in very large numbers","sold at a very low price","imported from far away"]}],"situationDistractors":["A factory poured waste chemicals into the river.","A company cut down an old forest and planted nothing.","A farm used so much water that the lake dried up.","A shop gave away thousands of plastic bags every day.","A power station burned coal day and night.","A boat caught every fish in the bay in one week."],"gapDistractors":[{"contextId":"u8_36_sustainable_gap_1","answer":"sustainable","wrong":["relentless","responsible","rough"]},{"contextId":"u8_36_sustainable_gap_2","answer":"sustainable","wrong":["relentless","rough","curved"]},{"contextId":"u8_36_sustainable_gap_3","answer":"sustainable","wrong":["relentless","rough","qualified"]}],"spellingErrors":["sustanable","sustainible","sustainabel","sustenable","sustainble","susstainable"],"wordFamilyForms":[{"form":"sustainable","partOfSpeech":"adjective","example":"The company only uses sustainable materials in its packaging.","pedagogicallyUseful":true},{"form":"sustainability","partOfSpeech":"noun","example":"Sustainability is now a key part of every product design.","pedagogicallyUseful":true,"altExample":"The new manager is in charge of sustainability across the company."},{"form":"sustain","partOfSpeech":"verb","example":"The planet cannot sustain this level of pollution.","pedagogicallyUseful":true,"altExample":"The small farm cannot sustain a family of six."}],"masteryPassages":[{"passageId":"u8_36_sustainable_passage_1","contextId":"u8_36_sustainable_gap_1","text":"The new office has solar panels on the roof and collects rainwater for the toilets. The architect wanted it to be as ____ as possible, so it uses very little energy.","answer":"sustainable"},{"passageId":"u8_36_sustainable_passage_2","contextId":"u8_36_sustainable_gap_2","text":"For every tree the company cuts down, it plants three new ones. This makes its furniture ____, because the forests will never disappear.","answer":"sustainable"}],"contextDependentParaphrases":[],"wrongParaphrases":["environmentally harmful","extremely expensive","completely modern"],"misleadingDistractors":["very cheap to produce in large amounts","popular for a short time only","made using the latest technology"],"teacherNote":"Adjective: able to continue without harming the environment or using up natural resources (sustainable energy, sustainable farming). Boundary: sustainable can also mean able to continue in general (sustainable growth), but Unit 8 focuses on the environmental sense. The noun sustainability and the verb sustain are taught in the Word Family pathway."}]'::jsonb,'["sustainability","sustain"]'::jsonb,'["sustainable energy","sustainable development","environmentally sustainable"]'::jsonb,'live'),
('vocab_transformed','transformed','verb','completely changed the appearance, form or character of something, usually improving it','[{"senseId":"transformed_1","meaning":"completely changed the appearance, form or character of something, usually improving it","acceptedParaphrases":["completely changed","totally altered"],"masteryContexts":[{"contextId":"u8_37_transformed_meaning","text":"The new manager transformed the failing shop into one of the most successful in the city.","meaning":"changed completely for the better","wrongMeanings":["closed down completely","copied exactly","left unchanged"]},{"contextId":"u8_37_transformed_paraphrase","text":"Mobile phones have transformed the way that people do business.","meaning":"changed in a very big way","wrongMeanings":["slowed down slightly","stopped completely","kept the same"]}],"situationDistractors":["A painter touched up a small scratch on a door.","An office stayed exactly the same for thirty years.","A manager moved one chair to the other side of the room.","A shop changed the price of one item.","A worker replaced a light bulb in the corridor.","A café added salt to one dish on its menu."],"gapDistractors":[{"contextId":"u8_37_transformed_gap_1","answer":"transformed","wrong":["concerned","qualified","curved"]},{"contextId":"u8_37_transformed_gap_2","answer":"transformed","wrong":["concerned","qualified","curved"]},{"contextId":"u8_37_transformed_gap_3","answer":"transformed","wrong":["concerned","curved","qualified"]}],"spellingErrors":["transfromed","transformd","tranformed","transfored","transformmed","transfermed"],"wordFamilyForms":[{"form":"transformed","partOfSpeech":"verb","example":"The new owners transformed the empty shop into a busy café.","pedagogicallyUseful":true},{"form":"transform","partOfSpeech":"verb","example":"New technology could transform the way we travel.","pedagogicallyUseful":true,"altExample":"A little paint can transform a dull office."},{"form":"transformation","partOfSpeech":"noun","example":"The transformation of the old harbour took ten years.","pedagogicallyUseful":true,"altExample":"Visitors are amazed by the transformation of the old station."}],"masteryPassages":[{"passageId":"u8_37_transformed_passage_1","contextId":"u8_37_transformed_gap_1","text":"Five years ago, the riverside was full of empty factories and rubbish. A huge project has ____ it into a park with cafés, walking paths and an open-air theatre.","answer":"transformed"},{"passageId":"u8_37_transformed_passage_2","contextId":"u8_37_transformed_gap_2","text":"When Ms Patel took over the failing restaurant, it had almost no customers. She ____ the menu, the decoration and the service, and now people queue to get in.","answer":"transformed"}],"contextDependentParaphrases":[],"wrongParaphrases":["slightly repaired","carefully cleaned","quickly sold"],"misleadingDistractors":["slightly repaired","kept exactly the same","sold to a new owner"],"teacherNote":"Verb (past tense or past participle): completely changed the form, appearance or character of something, often for the better (transformed into, transformed the way). Boundary: transformed means a complete change; changed or altered can be small. The base verb transform and the noun transformation are taught in the Word Family pathway."}]'::jsonb,'["transform","transformation"]'::jsonb,'["transformed into","completely transformed","transformed the way"]'::jsonb,'live'),
('vocab_operator','operator','noun','a person whose job is to work a machine or a piece of equipment','[{"senseId":"operator_1","meaning":"a person whose job is to work a machine or a piece of equipment","acceptedParaphrases":["machine worker","person who controls a machine"],"masteryContexts":[{"contextId":"u8_38_operator_meaning","text":"The machine operator stopped the production line when she saw smoke.","meaning":"a person who works a machine","wrongMeanings":["a person who owns a factory","a person who designs a machine","a person who buys a machine"]},{"contextId":"u8_38_operator_paraphrase","text":"Each forklift operator must have a licence and two weeks of training.","meaning":"a person trained to drive equipment","wrongMeanings":["a person trained to sell equipment","a person paid to clean equipment","a person who invents equipment"]}],"situationDistractors":["A designer drew plans for a new machine.","A salesman showed a customer a brochure of tractors.","A manager signed an order for new equipment.","An inspector wrote a report about a broken crane.","A cleaner dusted a printer.","A customer bought a new washing machine."],"gapDistractors":[{"contextId":"u8_38_operator_gap_1","answer":"operator","wrong":["nutritionist","scientist","landscape"]},{"contextId":"u8_38_operator_gap_2","answer":"operator","wrong":["nutritionist","landscape","minority"]},{"contextId":"u8_38_operator_gap_3","answer":"operator","wrong":["nutritionist","landscape","technology"]}],"spellingErrors":["operater","opperator","operatar","oparator","operatior","opeator"],"wordFamilyForms":[{"form":"operator","partOfSpeech":"noun","example":"The operator checked the machine before starting her shift.","pedagogicallyUseful":true},{"form":"operate","partOfSpeech":"verb","example":"Only trained staff may operate the cutting machine.","pedagogicallyUseful":true,"altExample":"Can you operate a forklift truck?"},{"form":"operation","partOfSpeech":"noun","example":"The operation of the new machines requires special training.","pedagogicallyUseful":true,"altExample":"The factory is in operation twenty-four hours a day."}],"masteryPassages":[{"passageId":"u8_38_operator_passage_1","contextId":"u8_38_operator_gap_1","text":"The new printing machine is huge and dangerous. Only a trained ____ is allowed to switch it on and control its speed.","answer":"operator"},{"passageId":"u8_38_operator_passage_2","contextId":"u8_38_operator_gap_2","text":"The crane is taller than the office block next to it. High above the building site, the ____ sits in a small cabin at the top, moving the steel beams into place.","answer":"operator"}],"contextDependentParaphrases":[],"wrongParaphrases":["machine designer","machine seller","machine owner"],"misleadingDistractors":["a person who designs new machines","a person who sells machines","a person who inspects machines"],"teacherNote":"Noun: a person who works a machine or equipment (a machine operator, a crane operator); it can also mean a company that runs a service (a tour operator), which is not tested here. Boundary: an operator uses the machine; an engineer designs or repairs it. The verb operate and the noun operation are taught in the Word Family pathway."}]'::jsonb,'["operate","operation"]'::jsonb,'["a machine operator","a crane operator","a trained operator"]'::jsonb,'live'),
('vocab_nutritionist','nutritionist','noun','an expert who advises people about food and healthy eating','[{"senseId":"nutritionist_1","meaning":"an expert who advises people about food and healthy eating","acceptedParaphrases":["food and diet expert","expert on healthy eating"],"masteryContexts":[{"contextId":"u8_39_nutritionist_meaning","text":"The nutritionist told the athlete to eat more protein and less sugar.","meaning":"an expert in food and health","wrongMeanings":["a trainer for running and jumping","a cook in a sports club","a doctor for broken bones"]},{"contextId":"u8_39_nutritionist_paraphrase","text":"Before launching the new snack, the company asked a nutritionist to check how healthy it was.","meaning":"an expert who judges how healthy food is","wrongMeanings":["an expert who designs packaging","an expert who sets prices","an expert who advertises food"]}],"situationDistractors":["A chef cooked a large pot of pasta for the restaurant.","A farmer sold eggs at the market.","A waiter carried plates to a table.","A cashier scanned the food at the supermarket.","A delivery driver brought pizzas to an office.","A baker took bread out of the oven."],"gapDistractors":[{"contextId":"u8_39_nutritionist_gap_1","answer":"nutritionist","wrong":["operator","engineer","landscape"]},{"contextId":"u8_39_nutritionist_gap_2","answer":"nutritionist","wrong":["director","landscape","technology"]},{"contextId":"u8_39_nutritionist_gap_3","answer":"nutritionist","wrong":["landscape","technology","minority"]}],"spellingErrors":["nutritonist","nutrisionist","nutricionist","nutritionest","nutrishionist","nuttritionist"],"wordFamilyForms":[{"form":"nutritionist","partOfSpeech":"noun","example":"The nutritionist explained which foods give you the most energy.","pedagogicallyUseful":true},{"form":"nutrition","partOfSpeech":"noun","example":"Good nutrition is important for students during exams.","pedagogicallyUseful":true,"altExample":"The course covers nutrition, exercise and sleep."},{"form":"nutritious","partOfSpeech":"adjective","example":"The café serves cheap but nutritious meals.","pedagogicallyUseful":true,"altExample":"Lentils are cheap and very nutritious."}],"masteryPassages":[{"passageId":"u8_39_nutritionist_passage_1","contextId":"u8_39_nutritionist_gap_1","text":"Before the marathon, Leo wanted to eat the right food. His ____ told him to eat more pasta and drink more water in the days before the race.","answer":"nutritionist"},{"passageId":"u8_39_nutritionist_passage_2","contextId":"u8_39_nutritionist_gap_2","text":"The company wanted its new cereal to be as healthy as possible. It hired a ____ to check the amount of sugar, salt and fibre in every recipe.","answer":"nutritionist"}],"contextDependentParaphrases":[],"wrongParaphrases":["food and drink seller","sports and fitness coach","farm and garden worker"],"misleadingDistractors":["a person who cooks meals in a restaurant","a doctor who performs operations","a person who grows vegetables to sell"],"teacherNote":"Noun: an expert who advises people about food and healthy eating (a sports nutritionist). Boundary: a nutritionist advises on what to eat; a chef cooks the food. The noun nutrition and the adjective nutritious are taught in the Word Family pathway."}]'::jsonb,'["nutrition","nutritious"]'::jsonb,'["a sports nutritionist","see a nutritionist","advice from a nutritionist"]'::jsonb,'live'),
('vocab_director','director','noun','a senior manager who is in charge of a company or one of its departments','[{"senseId":"director_1","meaning":"a senior manager who is in charge of a company or one of its departments","acceptedParaphrases":["senior manager","person in charge of a company"],"masteryContexts":[{"contextId":"u8_40_director_meaning","text":"The sales director wants every shop to increase its profits by ten per cent.","meaning":"a senior manager in charge of a department","wrongMeanings":["a junior worker in a department","a customer of a department","a visitor to a department"]},{"contextId":"u8_40_director_paraphrase","text":"After twenty years with the company, she became its managing director.","meaning":"the person who runs a company","wrongMeanings":["the person who cleans a company","the person who audits a company","the person who sues a company"]}],"situationDistractors":["A trainee made coffee for the team on her first day.","A receptionist greeted visitors at the front desk.","A delivery driver unloaded boxes at the back door.","An intern photocopied a report.","A cleaner emptied the bins in the boardroom.","A customer asked for a refund at the till."],"gapDistractors":[{"contextId":"u8_40_director_gap_1","answer":"director","wrong":["landscape","technology","minority"]},{"contextId":"u8_40_director_gap_2","answer":"director","wrong":["landscape","technology","packaging"]},{"contextId":"u8_40_director_gap_3","answer":"director","wrong":["nutritionist","landscape","technology"]}],"spellingErrors":["directer","derector","directar","dirrector","diretor","directour"],"masteryPassages":[{"passageId":"u8_40_director_passage_1","contextId":"u8_40_director_gap_1","text":"Ms Obi started at the company as a secretary thirty years ago. Today she runs the whole business as its managing ____.","answer":"director"},{"passageId":"u8_40_director_passage_2","contextId":"u8_40_director_gap_2","text":"Every department in the company has its own head. The marketing ____ meets the other heads every Monday to discuss the week’s plans.","answer":"director"}],"contextDependentParaphrases":[],"wrongParaphrases":["junior assistant","new trainee","part-time cleaner"],"misleadingDistractors":["a new worker who is still training","a person who checks safety rules","a person who answers the phone at reception"],"teacherNote":"Noun: a senior manager in charge of a company or department (the managing director, the director of finance). Boundary: director also means the person in charge of a film or play; Unit 8 teaches the business sense. No family is taught because direct and direction are mainly used for giving the way or aiming something."}]'::jsonb,'[]'::jsonb,'["a managing director","the sales director","the director of a company"]'::jsonb,'live')
